head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > M > notifyDataChanged]<br/>트리 아이템이 ItemSet 으로 정의되었을때 바인딩 된 DataCollection 을 TreeView 컴포넌트에 새롭게 반영합니다.",
    "validation" : [
        "refreshCheckboxModel, refreshCheckboxDisableModel 속성 또는 setLabelByIndex() 메소드 등에 의해 DataCollection 에 반영된 값은 유지됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {            
        showCheckbox : true,    
    }

    let cList = $c.gcm.createCList(properties);    

    $c.gcm.createBasicTreeView(cList);
}


scwin.getText = function () {
    let rtn = target1.render.textContent;
    wf_body_bottom.getObj("scwin").setReturnValue("target1 text : " + rtn);
}



scwin.btn_setLabelByIndex_onclick = function (e) {
    target1.setLabelByIndex(1, "changeLabel_1");
};


scwin.btn_notifyDataChanged_onclick = function (e) {
	target1.notifyDataChanged();    

    scwin.getText();    
};
